# Calculate average path lengthavg_path <- mean_distance(net, directed=TRUE)cat("Average Path Length:", avg_path, "\n")# Get all distancesdist_matrix <- distances(net, weights=NA)cat("\nDistance Matrix (first few rows/columns):\n")print(head(round(dist_matrix, 2)))# Find distance from a specific media outlet (e.g., NY Times) to all othersnyt_distances <- distances(net,                          v=V(net)[media=="NY Times"],                         to=V(net),                         weights=NA)# Visualize distances from NY Times# Create color gradient for distancesoranges <- colorRampPalette(c("dark red", "gold"))col <- oranges(max(nyt_distances)+1)col <- col[nyt_distances+1]# Plot with distance-based colorsplot(net,      vertex.color=col,     vertex.label=round(nyt_distances,1),     edge.arrow.size=0.6,     vertex.label.color="white",     main="Distances from NY Times")# Find and visualize shortest path between specific nodes# Example: Path from MSNBC to New York Postnews_path <- shortest_paths(net,                          from=V(net)[media=="MSNBC"],                          to=V(net)[media=="New York Post"],                          output="both")# Generate colors for visualizationecol <- rep("gray80", ecount(net))ecol[unlist(news_path$epath)] <- "orange"vcol <- rep("gray40", vcount(net))vcol[unlist(news_path$vpath)] <- "gold"# Plot the shortest pathplot(net,     vertex.color=vcol,     edge.color=ecol,     edge.width=2,     edge.arrow.mode=0,     main="Shortest Path: MSNBC to New York Post")# Add path length informationpath_length <- length(unlist(news_path$vpath)) - 1title(sub=paste("Path Length:", path_length))# Find all neighbors of a specific node (e.g., Wall Street Journal)wsj_neighbors <- neighbors(net,                          V(net)[media=="Wall Street Journal"],                         mode="all")# Visualize neighborhoodvcol <- rep("grey40", vcount(net))vcol[V(net)$media=="Wall Street Journal"] <- "gold"vcol[wsj_neighbors] <- "#ff9d00"plot(net,     vertex.color=vcol,     vertex.label.cex=0.8,     main="Wall Street Journal's Network Neighborhood")# Calculate and visualize reciprocity in relationshipsreciprocal_edges <- which(is.mutual(net))E(net)$color <- "grey"E(net)$color[reciprocal_edges] <- "red"plot(net,     edge.color=E(net)$color,     vertex.label.cex=0.8,     main="Reciprocal Relationships in Media Network")# Add legendlegend("bottomleft",       c("One-way", "Reciprocal"),       lty=1,       col=c("grey", "red"),       bty="n")# Calculate assortativity by media typetype_assortativity <- assortativity_nominal(net,                                           V(net)$media.type,                                          directed=FALSE)# Calculate assortativity by audience sizesize_assortativity <- assortativity(net,                                   V(net)$audience.size,                                   directed=FALSE)# Calculate degree assortativitydegree_assortativity <- assortativity_degree(net,                                           directed=FALSE)cat("Assortativity by:\n")cat("Media Type:", type_assortativity, "\n")cat("Audience Size:", size_assortativity, "\n")cat("Degree:", degree_assortativity, "\n")